async function answerPolicyQuery(ticket) {
  const query = ticket.content;

  // Step 1: Query internal policy vector store
  let internalResults = await vectorStore.query({
    query,
    filters: { keywords: ['return policy', '60 days'] }
  });

  // Fallback: If internal results ambiguous, query public API
  if (!internalResults.confident) {
    const publicResults = await publicPolicyAPI.query(query);
    internalResults = mergeResults(internalResults, publicResults);
  }

  // Step 2: Extract policy with citations
  const answer = await qaPipeline.extract(internalResults, {
    includeCitations: true
  });

  // Step 3: Return concise answer with sources
  return formatAnswer(answer, internalResults.sources);
}
